CREATE TABLE asset (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, asset_code VARCHAR(64) NOT NULL, asset_name VARCHAR(128) NOT NULL, asset_type VARCHAR(32) NOT NULL, ownership_type VARCHAR(32) NOT NULL, operation_mode VARCHAR(32) NOT NULL, country_code VARCHAR(8), province_code VARCHAR(32), city_code VARCHAR(32), district_code VARCHAR(32), address VARCHAR(512), longitude DECIMAL(10,7), latitude DECIMAL(10,7), status VARCHAR(32) NOT NULL, management_team_id BIGINT NULL, created_by BIGINT NULL, created_at DATETIME(3) NOT NULL, updated_by BIGINT NULL, updated_at DATETIME(3) NOT NULL, version INT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, UNIQUE KEY uk_asset(tenant_id,asset_code), KEY idx_asset_status(tenant_id,status), KEY idx_asset_city(tenant_id,city_code));
CREATE TABLE asset_space (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, asset_id BIGINT NOT NULL, parent_space_id BIGINT NULL, space_code VARCHAR(64) NOT NULL, space_name VARCHAR(128) NOT NULL, space_type VARCHAR(32) NOT NULL, level_no INT NULL, sort_order INT NOT NULL DEFAULT 0, status VARCHAR(32) NOT NULL, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, version INT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, UNIQUE KEY uk_space(tenant_id,asset_id,space_code), KEY idx_space_parent(tenant_id,parent_space_id));
CREATE TABLE resource_unit (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, asset_id BIGINT NOT NULL, space_id BIGINT NULL, resource_code VARCHAR(64) NOT NULL, resource_name VARCHAR(128) NOT NULL, resource_type VARCHAR(32) NOT NULL, area DECIMAL(12,2) NULL, capacity INT NULL, rentable TINYINT NOT NULL DEFAULT 1, sellable TINYINT NOT NULL DEFAULT 0, physical_status VARCHAR(32) NOT NULL, sale_status VARCHAR(32) NOT NULL, version INT NOT NULL DEFAULT 0, deleted TINYINT NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY uk_resource(tenant_id,resource_code), KEY idx_res_asset(tenant_id,asset_id), KEY idx_res_status(tenant_id,physical_status,sale_status));
CREATE TABLE resource_schedule_guard (tenant_id BIGINT NOT NULL, resource_unit_id BIGINT NOT NULL, schedule_version BIGINT NOT NULL DEFAULT 0, updated_at DATETIME(3) NOT NULL, PRIMARY KEY(tenant_id,resource_unit_id));
CREATE TABLE resource_conflict_group (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, group_code VARCHAR(64) NOT NULL, group_type VARCHAR(32) NOT NULL, name VARCHAR(128) NOT NULL, status VARCHAR(32) NOT NULL, UNIQUE KEY uk_conflict_group(tenant_id,group_code));
CREATE TABLE resource_conflict_group_member (tenant_id BIGINT NOT NULL, group_id BIGINT NOT NULL, resource_unit_id BIGINT NOT NULL, PRIMARY KEY(tenant_id,group_id,resource_unit_id), KEY idx_conf_member_resource(tenant_id,resource_unit_id));
CREATE TABLE valuation (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, valuation_no VARCHAR(64) NOT NULL, asset_id BIGINT NOT NULL, resource_unit_id BIGINT NULL, valuation_version INT NOT NULL, suggested_rent DECIMAL(18,2) NULL, floor_rent DECIMAL(18,2) NULL, suggested_sale_price DECIMAL(18,2) NULL, floor_sale_price DECIMAL(18,2) NULL, valid_from DATETIME(3) NOT NULL, valid_until DATETIME(3) NULL, status VARCHAR(32) NOT NULL, report_file_id BIGINT NULL, UNIQUE KEY uk_valuation(tenant_id,valuation_no), KEY idx_valuation_resource(tenant_id,resource_unit_id,valuation_version));
CREATE TABLE offering (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, offering_code VARCHAR(64) NOT NULL, resource_unit_id BIGINT NOT NULL, source_valuation_id BIGINT NULL, offering_name VARCHAR(128) NOT NULL, offering_type VARCHAR(32) NOT NULL, pricing_model VARCHAR(32) NOT NULL, currency CHAR(3) NOT NULL, base_price DECIMAL(18,2) NULL, guidance_price DECIMAL(18,2) NULL, minimum_price DECIMAL(18,2) NULL, valid_from DATETIME(3) NOT NULL, valid_to DATETIME(3) NULL, minimum_duration_minutes BIGINT NULL, maximum_duration_minutes BIGINT NULL, status VARCHAR(32) NOT NULL, version INT NOT NULL DEFAULT 0, UNIQUE KEY uk_offering(tenant_id,offering_code), KEY idx_offer_res(tenant_id,resource_unit_id,status));
CREATE TABLE listing (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, listing_no VARCHAR(64) NOT NULL, offering_id BIGINT NOT NULL, resource_unit_id BIGINT NOT NULL, channel VARCHAR(32) NOT NULL, title VARCHAR(256) NOT NULL, description TEXT NULL, display_price DECIMAL(18,2) NULL, publish_start DATETIME(3) NULL, publish_end DATETIME(3) NULL, status VARCHAR(32) NOT NULL, data_version BIGINT NOT NULL DEFAULT 0, UNIQUE KEY uk_listing(tenant_id,listing_no), KEY idx_listing_channel(tenant_id,channel,status), KEY idx_listing_res(tenant_id,resource_unit_id));
CREATE TABLE resource_availability (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, resource_unit_id BIGINT NOT NULL, start_time DATETIME(3) NOT NULL, end_time DATETIME(3) NOT NULL, status VARCHAR(32) NOT NULL, reason_type VARCHAR(32) NULL, reason VARCHAR(512) NULL, source_type VARCHAR(32) NULL, source_id BIGINT NULL, version INT NOT NULL DEFAULT 0, KEY idx_avail(tenant_id,resource_unit_id,status,start_time,end_time));
CREATE TABLE resource_occupancy (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, resource_unit_id BIGINT NOT NULL, occupancy_type VARCHAR(32) NOT NULL, start_time DATETIME(3) NOT NULL, end_time DATETIME(3) NOT NULL, source_type VARCHAR(32) NOT NULL, source_id BIGINT NOT NULL, status VARCHAR(32) NOT NULL, version INT NOT NULL DEFAULT 0, KEY idx_occ_time(tenant_id,resource_unit_id,status,start_time,end_time), KEY idx_occ_source(tenant_id,source_type,source_id));
CREATE TABLE reservation (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, reservation_no VARCHAR(64) NOT NULL, customer_id BIGINT NOT NULL, opportunity_id BIGINT NULL, quotation_version_id BIGINT NOT NULL, hold_expire_at DATETIME(3) NOT NULL, deposit_required TINYINT NOT NULL DEFAULT 0, deposit_amount DECIMAL(18,2) NOT NULL DEFAULT 0, deposit_paid_amount DECIMAL(18,2) NOT NULL DEFAULT 0, status VARCHAR(32) NOT NULL, converted_agreement_id BIGINT NULL, version INT NOT NULL DEFAULT 0, created_at DATETIME(3) NOT NULL, updated_at DATETIME(3) NOT NULL, UNIQUE KEY uk_resv(tenant_id,reservation_no), KEY idx_resv_expire(tenant_id,status,hold_expire_at), KEY idx_resv_customer(tenant_id,customer_id));
CREATE TABLE reservation_item (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, reservation_id BIGINT NOT NULL, resource_unit_id BIGINT NOT NULL, offering_id BIGINT NOT NULL, start_time DATETIME(3) NOT NULL, end_time DATETIME(3) NOT NULL, quoted_price DECIMAL(18,2) NOT NULL, KEY idx_resv_item(tenant_id,resource_unit_id,start_time,end_time));
CREATE TABLE renovation_order (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, renovation_no VARCHAR(64) NOT NULL, resource_unit_id BIGINT NOT NULL, start_time DATETIME(3) NOT NULL, end_time DATETIME(3) NOT NULL, status VARCHAR(32) NOT NULL, reason VARCHAR(512) NULL, UNIQUE KEY uk_reno(tenant_id,renovation_no), KEY idx_reno_res(tenant_id,resource_unit_id,status));
CREATE TABLE maintenance_order (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, maintenance_no VARCHAR(64) NOT NULL, resource_unit_id BIGINT NOT NULL, emergency TINYINT NOT NULL DEFAULT 0, planned_start DATETIME(3) NULL, planned_end DATETIME(3) NULL, status VARCHAR(32) NOT NULL, problem TEXT NULL, UNIQUE KEY uk_maint(tenant_id,maintenance_no));
CREATE TABLE operation_work_order (id BIGINT PRIMARY KEY, tenant_id BIGINT NOT NULL, work_order_no VARCHAR(64) NOT NULL, work_order_type VARCHAR(32) NOT NULL, resource_unit_id BIGINT NULL, customer_id BIGINT NULL, agreement_id BIGINT NULL, priority VARCHAR(16) NOT NULL, status VARCHAR(32) NOT NULL, assignee_id BIGINT NULL, sla_due_at DATETIME(3) NULL, description TEXT NULL, UNIQUE KEY uk_workorder(tenant_id,work_order_no), KEY idx_workorder_status(tenant_id,status,sla_due_at));
